def _spec(record, spec_field, default=None):
    """Get a value from a spec field (nfe40_*, cte40_*) if available.

    Use this ONLY for fields that do NOT exist in l10n_br_fiscal base.
    For fields that already exist (document_key, amount_icms_base, etc.)
    just use them directly — the spec modules define them as 'related'.
    """
    if hasattr(record, spec_field):
        val = getattr(record, spec_field)
        if val or val == 0:
            return val
    return default


def _digits(value):
    return misc.punctuation_rm(value or "")


def _unit(uom):
    """UNID (0190, 0200, C170): o código da unidade, até 6 posições.

    O nome ("Unidades") não cabe no campo C 006 e não é o que a nota traz.
    """
    return (uom.code or uom.name or "")[:6] if uom else ""


# As datas do documento fiscal (document_date, date_in_out) são Datetime em
# UTC. Uma nota emitida às 22h de 30/09 em Brasília é 01h de 01/10 em UTC: sem
# converter, ela cai no mês seguinte e sai com a data errada no C100.
DEFAULT_TZ = "America/Sao_Paulo"


def _tz(declaration):
    return pytz.timezone(declaration.company_id.partner_id.tz or DEFAULT_TZ)


def _local_date(declaration, value):
    """Data local (do estabelecimento) de um Datetime UTC."""
    if not value:
        return False
    if not isinstance(value, datetime):
        return value
    return pytz.utc.localize(value).astimezone(_tz(declaration)).date()


def _utc_bounds(declaration):
    """Início e fim do período da declaração, em UTC, para buscar Datetime."""
    tz = _tz(declaration)
    start = tz.localize(datetime.combine(declaration.DT_INI, time.min))
    end = tz.localize(datetime.combine(declaration.DT_FIN, time.max))
    return (
        start.astimezone(pytz.utc).replace(tzinfo=None),
        end.astimezone(pytz.utc).replace(tzinfo=None),
    )


