DOC_MODELS_A = ("SE",)
DOC_MODELS_C100 = ("01", "1B", "04", "55", "65")
DOC_MODELS_D100 = ("07", "08", "8B", "09", "10", "11", "26", "27", "57", "63", "67")

# NT 11/2026: enquanto a EFD-Contribuições não recebe os documentos novos da
# reforma, a NFAg (modelo 75) e a NFGas (modelo 76) são escrituradas com o
# código do documento em papel equivalente, 29 e 28, nos registros que já os
# recebem (C500/C600), sem o campo CHV_DOCe.
COD_MOD_NT_11_2026 = {"75": "29", "76": "28"}


def _cod_mod(document_type_code):
    """COD_MOD do leiaute para o modelo do documento (NT 11/2026)."""
    code = document_type_code or ""
    return COD_MOD_NT_11_2026.get(code, code)


# Situação do documento (tabela 4.1.2) pelo estado do documento eletrônico. O
# `state_fiscal` só é gravado no cancelamento, e milhares de notas autorizadas
# ficam com ele vazio; o `state_edoc` é o que a SEFAZ devolveu.
COD_SIT_BY_STATE_EDOC = {
    "autorizada": "00",
    "cancelada": "02",
    "denegada": "04",
    "inutilizada": "05",
}

# Situações em que o documento não tem registros filhos (Guia, C100: "exceto
# em relação aos documentos fiscais referentes à nota fiscal cancelada
# (código 02 ou 03), NF-e denegada (04) ou numeração inutilizada (05), os quais
# não devem ser escriturados os registros filhos de C100").
COD_SIT_WITHOUT_CHILDREN = ("02", "03", "04", "05")

# Tributos da reforma (CBS, IBS e IS). NT 11/2026: "estes valores não devem
# ser somados aos valores dos itens ou dos documentos fiscais no ano de 2026".
NEW_TAX_DOMAINS = ("cbs", "ibs", "is")


def _new_taxes_added_to_total(line):
    """CBS, IBS e IS que o motor fiscal somou ao total da linha.

    O total fiscal soma todo tributo cujo grupo não é "incluído no preço"
    (`tax_include`). Com o grupo da CBS/IBS configurado assim, o valor destacado
    em 2026 iria para o VL_DOC, o que a NT 11/2026 proíbe.
    """
    total = 0.0
    for domain in NEW_TAX_DOMAINS:
        tax = line[f"{domain}_tax_id"] if f"{domain}_tax_id" in line._fields else None
        value_field = f"{domain}_value"
        if not tax or value_field not in line._fields:
            continue
        group = tax.tax_group_id
        if group.tax_withholding or group.tax_include:
            continue
        total += line[value_field]
    return total


def _document_total(document):
    """VL_DOC sem CBS, IBS e IS (NT 11/2026)."""
    return document.fiscal_amount_total - sum(
        _new_taxes_added_to_total(line) for line in document.fiscal_line_ids
    )


