# Tabela 4.3.5 (código da contribuição social apurada) a partir do CST e do
# regime, como o PVA monta ao "Gerar Apurações" (Guia 1.35, Registro M210,
# campo 02). Chave: (CST, cumulativo?).
COD_CONT_BY_CST = {
    ("01", False): "01",
    ("02", False): "02",
    ("03", False): "03",
    ("05", False): "32",
    ("01", True): "51",
    ("02", True): "52",
    ("03", True): "53",
    ("05", True): "31",
}
# CST que geram contribuição (M210). Os demais de saída (04, 06, 07, 08, 09)
# vão para o M400/M800 (receitas sem contribuição), e 49 não entra em nenhum.
CST_WITH_CONTRIBUTION = ("01", "02", "03", "05")
CST_WITHOUT_CONTRIBUTION = ("04", "06", "07", "08", "09")

# Alíquotas básicas (Guia, M210 campo 02): 1,65/7,6 no não cumulativo e
# 0,65/3 no cumulativo. É o que separa um CST 01 de cada regime quando a
# pessoa jurídica escritura os dois (COD_INC_TRIB = 3).
CUMULATIVE_BASIC_RATES = {"pis": 0.65, "cofins": 3.0}
NON_CUMULATIVE_BASIC_RATES = {"pis": 1.65, "cofins": 7.6}

# Códigos de receita do DARF (M205/M605), fixados pela RFB: PIS 6912 (não
# cumulativo) / 8109 (cumulativo), COFINS 5856 / 2172.
COD_REC = {
    ("pis", "non_cumulative"): "691201",
    ("pis", "cumulative"): "810902",
    ("cofins", "non_cumulative"): "585601",
    ("cofins", "cumulative"): "217201",
}
# Campo do M200/M600 a que o M205/M605 se refere: 08 é o não cumulativo a
# recolher (VL_CONT_NC_REC) e 12 o cumulativo (VL_CONT_CUM_REC).
NUM_CAMPO_BY_REGIME = {"non_cumulative": "08", "cumulative": "12"}


def _is_cumulative_line(tax, cst, rate, declaration):
    """O item foi tributado no regime cumulativo?

    Para quem escritura só um regime (COD_INC_TRIB 1 ou 2), o regime é o da
    escrituração. Quem escritura os dois (3) separa pela alíquota básica.
    """
    regime = declaration._get_cod_inc_trib()
    if regime == "1":
        return False
    if regime == "2":
        return True
    return abs(rate - CUMULATIVE_BASIC_RATES[tax]) < 0.0001


def _find_assessment(env, declaration, tax_domain, regime):
    """A apuração ENCERRADA deste tributo e regime no período."""
    return env["l10n_br_tax.assessment"].search(
        [
            ("company_id", "=", declaration.company_id.id),
            ("tax_domain", "=", tax_domain),
            ("regime", "=", regime),
            ("date_from", ">=", declaration.DT_INI),
            ("date_to", "<=", declaration.DT_FIN),
            # só a apuração encerrada entra num arquivo entregue
            ("state", "=", "posted"),
        ],
        limit=1,
    )


def _contribution_details(env, declaration, tax):
    """Detalhe da contribuição (M210/M610) a partir dos itens escriturados.

    O Guia 1.35 (Registro M210, campos 03 e 04) valida a receita bruta e a base
    de cálculo de cada M210 contra a soma dos itens dos blocos A, C, D e F com o
    mesmo CST e alíquota: o PVA recusa um M210 que não feche com os
    documentos. Por isso o detalhe é somado dos registros do próprio arquivo,
    não das linhas da apuração, cujo imposto contábil não guarda alíquota (o
    `account.tax` da localização é um só por tributo, com alíquota zero).
    """
    groups = OrderedDict()

    def add(cst, rate, item_value, base, value):
        if cst not in CST_WITH_CONTRIBUTION:
            return
        if cst == "05" and not value:
            # CST 05 sem valor é a revenda do substituído: sem contribuição,
            # vai para o M400/M800
            return
        cumulative = _is_cumulative_line(tax, cst, rate, declaration)
        cod_cont = COD_CONT_BY_CST.get((cst, cumulative))
        key = (cod_cont, round(rate, 4))
        group = groups.setdefault(
            key,
            {
                "COD_CONT": cod_cont,
                "ALIQ": round(rate, 4),
                "VL_REC_BRT": 0.0,
                "VL_BC_CONT": 0.0,
                "VL_CONT_APUR": 0.0,
                "cumulative": cumulative,
            },
        )
        group["VL_REC_BRT"] += item_value
        group["VL_BC_CONT"] += base
        group["VL_CONT_APUR"] += value

    domain = [("declaration_id", "=", declaration.id)]
    for line in env["l10n_br_sped.efd_pis_cofins.c170"].search(domain):
        if line.reg_C170_ids_RegistroC100_id.IND_OPER != "1":
            continue
        add(
            line[f"CST_{tax.upper()}"],
            line[f"ALIQ_{tax.upper()}"],
            line.VL_ITEM,
            line[f"VL_BC_{tax.upper()}"],
            line[f"VL_{tax.upper()}"],
        )
    for line in env["l10n_br_sped.efd_pis_cofins.a170"].search(domain):
        if line.reg_A170_ids_RegistroA100_id.IND_OPER != "1":
            continue
        add(
            line[f"CST_{tax.upper()}"],
            line[f"ALIQ_{tax.upper()}"],
            line.VL_ITEM,
            line[f"VL_BC_{tax.upper()}"],
            line[f"VL_{tax.upper()}"],
        )
    for group in groups.values():
        for field in ("VL_REC_BRT", "VL_BC_CONT", "VL_CONT_APUR"):
            group[field] = round(group[field], 2)
    return list(groups.values())


# Tabela da natureza da receita de cada CST sem contribuição (Guia 1.35,
# Registro M410, campo 02 NAT_REC): 4.3.10 monofásicos (04), 4.3.12
# substituição tributária (05), 4.3.13 alíquota zero (06), 4.3.14 isenção
# (07), 4.3.15 sem incidência (08) e 4.3.16 suspensão (09).
NAT_REC_TABLE_BY_CST = {
    "04": "4.3.10",
    "05": "4.3.12",
    "06": "4.3.13",
    "07": "4.3.14",
    "08": "4.3.15",
    "09": "4.3.16",
}


def _nat_rec(declaration, product, cst):
    """Natureza da receita (NAT_REC) do item sem contribuição.

    1. Regra configurada (`l10n_br_sped_efd_pis_cofins.nat_rec.rule`), da
       empresa ou geral, pelo CST e pelo prefixo de NCM mais longo. É para a
       natureza que depende do enquadramento legal e não do NCM, como a
       maior parte da tabela 4.3.15 (sem incidência), que o contador decide.
    2. A tabela oficial pelo NCM (`l10n_br_fiscal.tax.pis.cofins`, com as
       faixas de NCM das tabelas 4.3.10 a 4.3.16), quando ela dá uma natureza
       só.
    """
    env = declaration.env
    ncm_code = _digits(product.ncm_id.code) if "ncm_id" in product._fields else ""
    cache = env.cr.cache.setdefault("efd_pis_cofins_nat_rec", {})
    key = (declaration.company_id.id, cst, ncm_code)
    if key in cache:
        return cache[key]
    result = env["l10n_br_sped_efd_pis_cofins.nat_rec.rule"]._find(
        declaration.company_id, cst, ncm_code
    )
    table = NAT_REC_TABLE_BY_CST.get(cst)
    if not result and table and product.ncm_id:
        natures = env["l10n_br_fiscal.tax.pis.cofins"].search(
            [("ncm_ids", "in", product.ncm_id.ids), ("sped_table", "=", table)]
        )
        codes = set(natures.mapped("code"))
        result = codes.pop() if len(codes) == 1 else ""
    cache[key] = result
    return result


def _revenue_without_contribution(env, declaration, tax):
    """Receitas sem contribuição (M400/M800), por CST e natureza da receita.

    Somadas dos itens de saída com CST 04, 06, 07, 08 e 09 (Guia, M400 campo
    03: o valor é recuperado dos registros dos blocos A, C, D e F; M410: um
    registro por natureza da receita e conta contábil).
    """
    groups = OrderedDict()
    domain = [("declaration_id", "=", declaration.id)]
    lines = env["l10n_br_sped.efd_pis_cofins.c170"].search(domain)
    for line in lines:
        if line.reg_C170_ids_RegistroC100_id.IND_OPER != "1":
            continue
        cst = line[f"CST_{tax.upper()}"]
        if cst not in CST_WITHOUT_CONTRIBUTION and not (
            cst == "05" and not line[f"VL_{tax.upper()}"]
        ):
            continue
        fiscal_line = env["l10n_br_fiscal.document.line"].browse(line.res_id)
        nat_rec = _nat_rec(declaration, fiscal_line.product_id, cst)
        group = groups.setdefault(cst, {"VL_TOT_REC": 0.0, "NAT_REC": OrderedDict()})
        group["VL_TOT_REC"] += line.VL_ITEM
        key = (nat_rec, line.COD_CTA or "")
        group["NAT_REC"][key] = group["NAT_REC"].get(key, 0.0) + line.VL_ITEM
    return groups


# Código do ajuste da contribuição (tabela 4.3.8, M220/M620 campo 04). A
# redução de benefícios da LC 224/2025 (NT 12/2026) é ajuste de acréscimo por
# legislação tributária.
COD_AJ_DEFAULT = "03"


def _assessment_adjustments(env, declaration, tax):
    """Ajustes manuais da apuração encerrada, no formato do M220/M620.

    Débito manual é ajuste de acréscimo (IND_AJ 1) e estorno de débito é
    ajuste de redução (IND_AJ 0). O código da tabela 4.3.8 vem do campo
    "Código do ajuste" da linha (2 posições), ou 03 (legislação tributária),
    que é onde a NT 12/2026 enquadra a LC 224/2025.
    """
    result = {}
    for regime in ("non_cumulative", "cumulative"):
        assessment = _find_assessment(env, declaration, tax, regime)
        adjustments = []
        for line in assessment.line_ids.filtered(lambda ln: ln.source == "manual"):
            if line.kind == "debit":
                ind_aj = "1"
            elif line.kind == "debit_reversal":
                ind_aj = "0"
            else:
                continue
            code = (line.adjustment_code or "").strip()
            adjustments.append(
                {
                    "IND_AJ": ind_aj,
                    "VL_AJ": round(line.tax_amount, 2),
                    "COD_AJ": code if len(code) == 2 else COD_AJ_DEFAULT,
                    "DESCR_AJ": line.description or "",
                    "DT_REF": assessment.date_to,
                }
            )
        result[regime] = adjustments
    return result


def nfe_di_available(env):
    """Whether the ``<DI>`` group of the NF-e items can be read.

    ``nfe.40.di`` is a spec model of l10n_br_nfe: it only gets a table once
    spec_driven_model makes it concrete, so a database with l10n_br_nfe
    installed may still have no ``nfe_40_di`` (no NF-e with a ``<DI>`` stored
    yet). Checking only that the model is registered then fails the whole
    pull with "relation nfe_40_di does not exist".
    """
    return "nfe.40.di" in env and table_exists(env.cr, "nfe_40_di")


class Registro0000(models.Model):
    "Abertura do Arquivo Digital e Identificação da Pessoa Jurídica"

    _description = textwrap.dedent(f"    {__doc__}")
    _name = "l10n_br_sped.efd_pis_cofins.0000"
    _inherit = ["l10n_br_sped.efd_pis_cofins.6.0000"]
    _odoo_model = "res.company"

    # monthly book: the default period is the month just closed
    DT_INI = fields.Date(default=lambda self: previous_month(self.env)[0])
    DT_FIN = fields.Date(default=lambda self: previous_month(self.env)[1])

    # Guia Prático 1.35, Registro 0000, campo 14: valores válidos 0, 1, 2, 3,
    # 4 e 9 (a seleção gerada só trazia 0 e 1).
    IND_ATIV = fields.Selection(
        [
            ("0", "Industrial ou equiparado a industrial"),
            ("1", "Prestador de serviços"),
            ("2", "Atividade de comércio"),
            (
                "3",
                "Pessoas jurídicas referidas nos §§ 6º, 8º e 9º do art. 3º da Lei nº 9.718/98",
            ),
            ("4", "Atividade imobiliária"),
            ("9", "Outros"),
        ],
        string="Indicador tipo atividade",
        default="2",
    )

    cod_inc_trib = fields.Selection(
        [
            ("1", "1 - Exclusivamente no regime não cumulativo"),
            ("2", "2 - Exclusivamente no regime cumulativo"),
            ("3", "3 - Nos regimes não cumulativo e cumulativo"),
        ],
        string="Regime da escrituração (0110)",
        compute="_compute_cod_inc_trib",
        store=True,
        readonly=False,
        help="Campo 02 do registro 0110. Vem do regime de apuração do lucro "
        "da empresa (Lucro Real: não cumulativo; os demais: cumulativo) e pode "
        "ser trocado na declaração.",
    )

    establishment_ids = fields.Many2many(
        comodel_name="res.company",
        relation="l10n_br_sped_efd_pis_cofins_establishment_rel",
        column1="declaration_id",
        column2="company_id",
        string="Estabelecimentos",
        compute="_compute_establishment_ids",
        store=True,
        readonly=False,
        help="A EFD-Contribuições é entregue pela pessoa jurídica, centralizada "
        "na matriz, com um registro 0140 e um C010 por estabelecimento. Por "
        "padrão entram a empresa da declaração e as suas filiais; retire a "
        "filial que não deve ser escriturada (uma loja de teste, por exemplo).",
    )

    @api.model
    def _append_top_view_elements(self, group, inline=False):
        """Regime and establishments where the user can check them.

        Both have defaults (the company's profit regime, the company and its
        branches) but the user has to see them: a test store must be taken out
        of the establishments, and a regime change is a decision to review.
        """
        res = super()._append_top_view_elements(group)
        group.append(E.field(name="cod_inc_trib", readonly=EDITABLE_ON_DRAFT))
        group.append(
            E.field(
                name="establishment_ids",
                widget="many2many_tags",
                readonly=EDITABLE_ON_DRAFT,
            )
        )
        return res

    def _sped_companies(self):
        # one file for the whole legal entity: 0140/C010 per establishment
        return super()._sped_companies() | self.establishment_ids

    @api.depends("company_id")
    def _compute_cod_inc_trib(self):
        for declaration in self:
            profit = declaration.company_id.profit_calculation
            declaration.cod_inc_trib = "1" if profit == "real" else "2"

    @api.depends("company_id")
    def _compute_establishment_ids(self):
        for declaration in self:
            company = declaration.company_id
            declaration.establishment_ids = company | self.env["res.company"].search(
                [("id", "child_of", company.id)]
            )

    def _get_cod_inc_trib(self):
        self.ensure_one()
        return self.cod_inc_trib or "2"

    def _is_non_cumulative(self):
        return self._get_cod_inc_trib() in ("1", "3")

    @api.depends("company_id", "DT_INI", "DT_FIN", "establishment_ids")
    def _compute_fiscal_documents(self):
        """Documentos da pessoa jurídica que geram receita ou crédito.

        Diferente das outras escriturações, a EFD-Contribuições junta todos os
        estabelecimentos da pessoa jurídica (Guia 1.35, Registro 0140). E não
        leva documento que não gera receita nem crédito (Guia, Registro C100:
        "Não devem ser informados documentos fiscais que não se refiram a
        operações geradoras de receitas ou de créditos"), como a
        transferência entre filiais (CFOP 5152/5409/2152) e a remessa: o
        documento entra quando algum item tem CFOP com movimento financeiro.
        """
        result = super()._compute_fiscal_documents()
        for record in self:
            if record.debug:
                continue
            documents = self.env["l10n_br_fiscal.document"].search(
                [
                    ("company_id", "in", record.establishment_ids.ids),
                    (
                        "state_edoc",
                        "in",
                        ("autorizada", "cancelada", "denegada", "inutilizada"),
                    ),
                    ("document_date", ">=", _utc_bounds(record)[0]),
                    ("document_date", "<=", _utc_bounds(record)[1]),
                    (
                        "document_type_id.code",
                        "in",
                        DOC_MODELS_A + DOC_MODELS_C100 + DOC_MODELS_D100,
                    ),
                ]
            )
            documents = documents.filtered(
                lambda doc: any(
                    line.cfop_id.finance_move or not line.cfop_id
                    for line in doc.fiscal_line_ids
                )
            )
            if record._get_cod_inc_trib() == "2":
                # Exclusivamente cumulativo: a entrada não gera crédito, e o
                # documento que não gera receita nem crédito não precisa ser
                # informado (Guia 1.35, Seção 4: "não precisam ser informados
                # na EFD-Contribuições, documentos que não se refiram a
                # operações geradoras de receitas ou de créditos"). A
                # devolução de venda poderia ir com CST 98/99 "para fins de
                # transparência" (Guia, C100), mas é opcional.
                documents = documents.filtered(
                    lambda doc: doc.fiscal_operation_type != FISCAL_IN
                )
            lines = documents.fiscal_line_ids
            record.fiscal_document_ids = documents
            record.fiscal_document_partner_ids = documents.partner_id
            record.fiscal_document_line_ids = lines
            record.fiscal_product_ids = lines.product_id
            record.fiscal_operation_ids = documents.fiscal_operation_id
            record.fiscal_comment_ids = documents.comment_ids
            record.fiscal_uom_ids = lines.uom_id | lines.product_id.uom_id
        return result

    # ------------------------------------------------------------------
    # Atalhos por estabelecimento (cache por cursor: o pull é recursivo e
    # pediria a mesma coisa uma vez por registro pai)
    # ------------------------------------------------------------------

    def _sped_cache(self, key, builder):
        cache = self.env.cr.cache.setdefault("efd_pis_cofins", {})
        full_key = (self.id, key)
        if full_key not in cache:
            cache[full_key] = builder()
        return cache[full_key]

    def _establishment_documents(self, company, models_=None):
        self.ensure_one()

        def build():
            return {
                comp.id: self.fiscal_document_ids.filtered(
                    lambda d, comp=comp: d.company_id == comp
                )
                for comp in self.establishment_ids
            }

        documents = self._sped_cache("documents", build).get(
            company.id, self.env["l10n_br_fiscal.document"]
        )
        if models_:
            documents = documents.filtered(lambda d: d.document_type_id.code in models_)
        return documents

    def _item_code_map(self):
        """COD_ITEM de cada produto, sem repetir código no arquivo.

        O código interno (default_code) é o que o fiscal reconhece, mas dois
        produtos com o mesmo código (um ativo e outro arquivado, por exemplo)
        gerariam dois 0200 com a mesma chave, que o PVA recusa. Nesse caso o
        id do produto desempata.
        """
        self.ensure_one()

        def build():
            products = self.fiscal_product_ids
            seen = {}
            for product in products:
                seen.setdefault(product.default_code or "", []).append(product)
            result = {}
            for code, group in seen.items():
                for product in group:
                    if not code:
                        result[product.id] = str(product.id)
                    elif len(group) == 1:
                        result[product.id] = code[:60]
                    else:
                        result[product.id] = f"{code}-{product.id}"[:60]
            return result

        return self._sped_cache("item_codes", build)

    def _item_code(self, product):
        return self._item_code_map().get(product.id) or str(product.id)

    def _line_account_map(self):
        """Conta contábil (COD_CTA) de cada item, pela linha da fatura."""
        self.ensure_one()

        def build():
            move_lines = self.env["account.move.line"].search(
                [
                    (
                        "fiscal_document_line_id",
                        "in",
                        self.fiscal_document_line_ids.ids,
                    ),
                    ("display_type", "=", "product"),
                ]
            )
            return {ml.fiscal_document_line_id.id: ml.account_id for ml in move_lines}

        return self._sped_cache("line_accounts", build)

    def _line_account(self, fiscal_line):
        return self._line_account_map().get(fiscal_line.id, self.env["account.account"])

    def _check_assessment_matches(self, tax, assessments, vals):
        """Confronta o débito escriturado com o da apuração encerrada.

        O débito do M200/M600 vem dos documentos (o PVA exige que o M210 feche
        com os itens); o da apuração vem da contabilidade. A diferença é
        sintoma de documento sem lançamento, lançamento sem documento (a NFS-e
        emitida fora do Odoo, por exemplo) ou apuração desatualizada, e fica
        registrada no chatter para quem vai transmitir.
        """
        self.ensure_one()
        messages = []
        for regime, field in (
            ("non_cumulative", "VL_TOT_CONT_NC_PER"),
            ("cumulative", "VL_TOT_CONT_CUM_PER"),
        ):
            assessment = assessments[regime]
            booked = (
                assessment.debit_total + assessment.adjustment_debit_total
                if assessment
                else 0.0
            )
            declared = vals[field]
            if not assessment and not declared:
                continue
            if not assessment:
                messages.append(
                    f"{tax.upper()} {regime}: sem apuração encerrada no período; "
                    f"o arquivo declara {declared:.2f}."
                )
            elif abs(booked - declared) >= 0.01:
                messages.append(
                    f"{tax.upper()} {regime}: a apuração {assessment.name} tem "
                    f"débito de {booked:.2f} e os documentos escriturados somam "
                    f"{declared:.2f} (diferença {booked - declared:.2f})."
                )
        if messages:
            self.message_post(body="<br/>".join(messages))
        return messages

    @api.model
    def _odoo_domain(self, parent_record, declaration):
        return [("id", "=", declaration.company_id.id)]

    @api.model
    def _map_from_odoo(self, record, parent_record, declaration, index=0):
        return {
            # the layout code has 3 fixed positions ("006"); LAYOUT_VERSIONS
            # keeps the bare number the model names use
            "COD_VER": LAYOUT_VERSIONS["efd_pis_cofins"].zfill(3),
            "TIPO_ESCRIT": "0",  # 0 - Original; 1 - Retificadora
            # IND_SIT_ESP and NUM_REC_ANTERIOR stay blank: they only exist in
            # special situations and rectifications, and the validator refuses
            # a zero written where the layout wants emptiness
            "NOME": record.legal_name or record.name,
            "CNPJ": _digits(record.vat),
            "UF": record.state_id.code,
            "COD_MUN": _digits(record.city_id.ibge_code),
            "SUFRAMA": record.l10n_br_isuf_code or "",
            "IND_NAT_PJ": "00",  # Pessoa jurídica em geral (2 fixed positions)
        }

    def _get_validator_class(self):
        from .validator import EfdContribuicoesValidator

        return EfdContribuicoesValidator

    def validate_sped_text(self, text=None):
        """Validação estrutural (sped_base) com as regras da EFD-Contribuições."""
        self.ensure_one()
        if text is None:
            text = self._generate_sped_text()
        validator = self._get_validator_class()(text, self._get_validator_registers())
        return validator.validate()

    @api.model
    def _get_validator_registers(self):
        """{código: [(campo, obrigatório, tipo)]} a partir do spec 006."""
        registers = {}
        version = LAYOUT_VERSIONS["efd_pis_cofins"]
        prefix = f"l10n_br_sped.efd_pis_cofins.{version}."
        for model_name in self.env:
            if not model_name.startswith(prefix):
                continue
            spec = self.env[model_name]
            code = model_name[len(prefix) :].upper()
            registers[code] = [
                (name, bool(getattr(field, "out_required", False)), field.type)
                for name, field in spec._ordered_fields()
                if name.isupper()
                and field.type not in ("one2many", "many2one", "many2many")
            ]
        return registers


