class Registro0110(models.Model):
    "Regimes de Apuração da Contribuição Social e de Apropriação de Crédito"

    _description = textwrap.dedent(f"    {__doc__}")
    _name = "l10n_br_sped.efd_pis_cofins.0110"
    _inherit = "l10n_br_sped.efd_pis_cofins.6.0110"

    @api.model
    def _map_from_odoo(self, record, parent_record, declaration, index=0):
        cod_inc_trib = declaration._get_cod_inc_trib()
        vals = {"COD_INC_TRIB": cod_inc_trib}
        if cod_inc_trib in ("1", "3"):
            # Guia 1.35, Registro 0110, campos 03 e 04: obrigatórios quando há
            # regime não cumulativo; 1 = apropriação direta e 1 = alíquota
            # básica.
            vals.update({"IND_APRO_CRED": "1", "COD_TIPO_CONT": "1"})
        if cod_inc_trib == "2":
            # campo 05, só no cumulativo: 2 = regime de competência
            # (consolidado em F550), 9 = detalhado. Quem escritura documento a
            # documento informa 9.
            vals["IND_REG_CUM"] = "9"
        return vals


