class Registro0150(models.Model):
    "Tabela de Cadastro do Participante"

    _description = textwrap.dedent(f"    {__doc__}")
    _name = "l10n_br_sped.efd_pis_cofins.0150"
    _inherit = "l10n_br_sped.efd_pis_cofins.6.0150"

    _odoo_model = "res.partner"

    @api.model
    def _odoo_domain(self, parent_record, declaration):
        documents = declaration._establishment_documents(parent_record)
        # o parceiro arquivado depois da nota continua sendo o COD_PART dela
        return [("id", "in", documents.partner_id.ids), ("active", "in", (True, False))]

    @api.model
    def _map_from_odoo(self, record, parent_record, declaration, index=0):
        brazil = not record.country_id or record.country_id.code == "BR"
        country_code = (
            (record.country_id.bc_code or "1058") if record.country_id else "1058"
        )
        vals = {
            "COD_PART": str(record.id),
            "NOME": record.legal_name or record.name,
            # tabela de países do Banco Central, 5 posições (Brasil = 01058)
            "COD_PAIS": country_code.zfill(5),
            "IE": _digits(record.l10n_br_ie_code),
            "SUFRAMA": record.l10n_br_isuf_code or "",
            "END": record.street_name or record.street or "",
            "NUM": record.street_number or "",
            "COMPL": record.street2 or "",
            "BAIRRO": record.district or "",
        }
        if brazil:
            document = _digits(record.vat)
            vals["CNPJ" if len(document) == 14 else "CPF"] = document
            vals["COD_MUN"] = record.city_id.ibge_code or ""
        return vals


