    _odoo_model = "account.account"

    # Natureza da conta (campo 03) pelo tipo da conta no Odoo.
    _NAT_CC_BY_INTERNAL_GROUP = {
        "asset": "01",
        "liability": "02",
        "equity": "03",
        "income": "04",
        "expense": "04",
        "off": "05",
    }

    @api.model
    def _odoo_domain(self, parent_record, declaration):
        # Guia 1.35, Registro 0500, observação 1: só as contas que aparecem
        # nos registros escriturados (COD_CTA).
        accounts = self.env["account.account"]
        for account in declaration._line_account_map().values():
            accounts |= account
        return [("id", "in", accounts.ids)]

    @api.model
    def _map_from_odoo(self, record, parent_record, declaration, index=0):
        code = record.code or ""
        return {
            "DT_ALT": record.create_date.date()
            if record.create_date
            else declaration.DT_INI,
            "COD_NAT_CC": self._NAT_CC_BY_INTERNAL_GROUP.get(
                record.internal_group, "09"
            ),
            "IND_CTA": "A",
            "NIVEL": str(code.count(".") + 1),
            "COD_CTA": code,
            "NOME_CTA": (record.name or "")[:60],
        }


