class _EstablishmentBlockMixin(models.AbstractModel):
    """Registro de abertura do estabelecimento num bloco (A010, C010, ...).

    Um por estabelecimento que tenha documento do bloco: um A010 sem A100
    (ou um C010 sem C100) é registro pai sem filho, que o PVA recusa.
    """

    _name = "l10n_br_sped.efd_pis_cofins.establishment.block.mixin"
    _description = "Abertura do estabelecimento no bloco"

    _odoo_model = "res.company"
    _block_models = ()

    @api.model
    def _odoo_domain(self, parent_record, declaration):
        companies = declaration.establishment_ids.filtered(
            lambda comp: declaration._establishment_documents(comp, self._block_models)
        )
        return [("id", "in", companies.ids)]

    @api.model
    def _map_from_odoo(self, record, parent_record, declaration, index=0):
        return {"CNPJ": _digits(record.vat)}


