class RegistroC100(models.Model):
    "Documento - Nota Fiscal (código 01)"

    _description = textwrap.dedent(f"    {__doc__}")
    _name = "l10n_br_sped.efd_pis_cofins.c100"
    _inherit = "l10n_br_sped.efd_pis_cofins.6.c100"

    _odoo_model = "l10n_br_fiscal.document"

    @api.model
    def _odoo_domain(self, parent_record, declaration):
        documents = declaration._establishment_documents(parent_record, DOC_MODELS_C100)
        return [("id", "in", documents.ids)]

    @api.model
    def _map_from_odoo(self, record, parent_record, declaration, index=0):
        cod_sit = COD_SIT_BY_STATE_EDOC.get(record.state_edoc, "00")
        vals = {
            "IND_OPER": "0" if record.fiscal_operation_type == FISCAL_IN else "1",
            "IND_EMIT": "0" if record.issuer == DOCUMENT_ISSUER_COMPANY else "1",
            "COD_MOD": _cod_mod(record.document_type_id.code),
            "COD_SIT": cod_sit,
            "SER": record.document_serie or "",
            "NUM_DOC": _digits(record.document_number),
            "CHV_NFE": record.document_key or "",
        }
        if cod_sit in COD_SIT_WITHOUT_CHILDREN:
            # Guia 1.35, Registro C100: documento cancelado, denegado ou
            # inutilizado leva só REG, IND_OPER, IND_EMIT, COD_MOD, COD_SIT,
            # SER, NUM_DOC e CHV_NFE; os demais campos ficam vazios.
            return vals
        vals.update(
            {
                "COD_PART": str(record.partner_id.id),
                "DT_DOC": _local_date(declaration, record.document_date),
                "DT_E_S": _local_date(
                    declaration, record.date_in_out or record.document_date
                ),
                # NT 11/2026: o total do documento não soma CBS, IBS nem IS
                "VL_DOC": _document_total(record),
                "IND_PGTO": "0",
                "VL_DESC": record.amount_discount_value,
                "VL_MERC": record.amount_price_gross,
                "IND_FRT": str(_spec(record, "nfe40_modFrete", "9")),
                "VL_FRT": record.amount_freight_value,
                "VL_SEG": record.amount_insurance_value,
                "VL_OUT_DA": record.amount_other_value,
                "VL_BC_ICMS": record.amount_icms_base,
                "VL_ICMS": record.amount_icms_value,
                "VL_BC_ICMS_ST": record.amount_icmsst_base,
                "VL_ICMS_ST": record.amount_icmsst_value,
                "VL_IPI": record.amount_ipi_value,
                "VL_PIS": record.amount_pis_value,
                "VL_COFINS": record.amount_cofins_value,
                "VL_PIS_ST": record.amount_pisst_value,
                "VL_COFINS_ST": record.amount_cofinsst_value,
            }
        )
        return vals

    def _write_register_line(self, sped, code, rec, keys, line_count, register_spec):
        if rec.COD_SIT in COD_SIT_WITHOUT_CHILDREN:
            # documento sem dados (cancelado, denegado, inutilizado): os
            # campos de valor obrigatórios ficam vazios, não zerados
            self = self.with_context(efd_blank_zero=True)
        return super()._write_register_line(
            sped, code, rec, keys, line_count, register_spec
        )


