class RegistroC120(models.Model):
    "Complemento de Documento – Operações de Importação"

    _description = textwrap.dedent(f"    {__doc__}")
    _name = "l10n_br_sped.efd_pis_cofins.c120"
    _inherit = "l10n_br_sped.efd_pis_cofins.6.c120"

    # A DI/DUIMP vem do grupo DI da NF-e de importação (nfe.40.di, do
    # l10n_br_nfe), um por item. O C120 vai um por documento de importação
    # (Guia 1.35: não pode repetir NUM_DOC_IMP no mesmo C100).
    _odoo_model = "nfe.40.di"

    @api.model
    def _odoo_domain(self, parent_record, declaration):
        if (
            not nfe_di_available(self.env)
            or parent_record.state_edoc != "autorizada"
            or parent_record.fiscal_operation_type != FISCAL_IN
            or not any(
                (line.cfop_id.code or "").startswith("3")
                for line in parent_record.fiscal_line_ids
            )
        ):
            return [("id", "=", 0)]
        declarations = self.env["nfe.40.di"].search(
            [("nfe40_DI_prod_id", "in", parent_record.fiscal_line_ids.ids)],
            order="id",
        )
        first_by_number = {}
        for di in declarations:
            first_by_number.setdefault(di.nfe40_nDI, di.id)
        return [("id", "in", list(first_by_number.values()))]

    @api.model
    def _map_from_odoo(self, record, parent_record, declaration, index=0):
        number = record.nfe40_nDI or ""
        lines = (
            self.env["nfe.40.di"]
            .search(
                [
                    ("nfe40_nDI", "=", number),
                    ("nfe40_DI_prod_id", "in", parent_record.fiscal_line_ids.ids),
                ]
            )
            .mapped("nfe40_DI_prod_id")
        )
        return {
            # 0 = DI, 2 = DUIMP (a partir de 2019, Guia 1.35, C120 campo 02).
            # O número da DUIMP traz "BR" (26BR00015708790); o da DI é só
            # numérico.
            "COD_DOC_IMP": "2" if "BR" in number.upper() else "0",
            "NUM_DOC_IMP": _digits(number) if "BR" not in number.upper() else number,
            "VL_PIS_IMP": sum(lines.mapped("pis_value")),
            "VL_COFINS_IMP": sum(lines.mapped("cofins_value")),
        }

    # @api.model
    # def _map_from_odoo(self, record, parent_record, declaration, index=0):
    #     return {
    #         "COD_DOC_IMP": 0,  # Documento de importação: 0 – Declaração de Impor...
    #         "NUM_DOC_IMP": 0,  # Número do documento de Importação.
    #         "VL_PIS_IMP": 0,  # Valor pago de PIS na importação
    #         "VL_COFINS_IMP": 0,  # Valor pago de COFINS na importação
    #         "NUM_ACDRAW": 0,  # Número do Ato Concessório do regime Drawback
    #     }


class RegistroC170(models.Model):
    "Complemento de Documento – Itens do Documento"

    _description = textwrap.dedent(f"    {__doc__}")
    _name = "l10n_br_sped.efd_pis_cofins.c170"
    _inherit = "l10n_br_sped.efd_pis_cofins.6.c170"

    _odoo_model = "l10n_br_fiscal.document.line"

    @api.model
    def _odoo_domain(self, parent_record, declaration):
        if parent_record.state_edoc != "autorizada":
            # sem registro filho no cancelado, denegado e inutilizado
            return [("id", "=", 0)]
        return [("document_id", "=", parent_record.id)]

    @api.model
    def _map_from_odoo(self, record, parent_record, declaration, index=0):
        return {
            "NUM_ITEM": str(index + 1),
            "COD_ITEM": declaration._item_code(record.product_id),
            "DESCR_COMPL": record.name or "",
            "QTD": record.quantity,
            "UNID": _unit(record.uom_id),
            # NT 11/2026: o valor do item não soma CBS, IBS nem IS
            "VL_ITEM": record.price_gross,
            "VL_DESC": record.discount_value,
            "IND_MOV": "0" if record.cfop_id.stock_move else "1",
            # 3 positions: the origin digit prefixes the 2-digit CST, as the
            # ICMS book writes it. A line without a 2-digit CST (a CSOSN from
            # the Simples) has nothing valid to write in this optional field.
            "CST_ICMS": (record.icms_origin or "0") + record.icms_cst_code
            if record.icms_cst_code and len(record.icms_cst_code) == 2
            else "",
            "CFOP": record.cfop_id.code or "",
            "COD_NAT": str(record.fiscal_operation_id.id or ""),
            "VL_BC_ICMS": record.icms_base,
            "ALIQ_ICMS": record.icms_percent,
            "VL_ICMS": record.icms_value,
            "VL_BC_ICMS_ST": record.icmsst_base,
            "ALIQ_ST": record.icmsst_percent,
            "VL_ICMS_ST": record.icmsst_value,
            "IND_APUR": "0" if record.ipi_cst_code else "",
            "CST_IPI": record.ipi_cst_code or "",
            "VL_BC_IPI": record.ipi_base,
            "ALIQ_IPI": record.ipi_percent,
            "VL_IPI": record.ipi_value,
            "CST_PIS": record.pis_cst_code or "",
            "VL_BC_PIS": record.pis_base,
            "ALIQ_PIS": record.pis_percent,
            "VL_PIS": record.pis_value,
            "CST_COFINS": record.cofins_cst_code or "",
            "VL_BC_COFINS": record.cofins_base,
            "ALIQ_COFINS": record.cofins_percent,
            "VL_COFINS": record.cofins_value,
            # Guia 1.35, Registro 0500: conta obrigatória para quem apura no
            # não cumulativo (erro a partir de 11/2017)
            "COD_CTA": declaration._line_account(record).code or "",
        }

    # CST com base, alíquota e valor obrigatórios no C170 (o PGE recusa o
    # campo vazio mesmo quando o valor é zero): os que geram contribuição ou
    # crédito.
    _CST_WITH_VALUES = ("01", "02", "03", "05") + tuple(
        str(cst) for cst in range(50, 67)
    )

    def _write_register_line(self, sped, code, rec, keys, line_count, register_spec):
        zero_fields = set()
        for tax in ("PIS", "COFINS"):
            if rec[f"CST_{tax}"] in self._CST_WITH_VALUES:
                zero_fields |= {f"VL_BC_{tax}", f"ALIQ_{tax}", f"VL_{tax}"}
        if zero_fields:
            self = self.with_context(efd_zero_fields=zero_fields)
        return super()._write_register_line(
            sped, code, rec, keys, line_count, register_spec
        )


