class RegistroD100(models.Model):
    "Aquisição de Serviços de Transportes"

    _description = textwrap.dedent(f"    {__doc__}")
    _name = "l10n_br_sped.efd_pis_cofins.d100"
    _inherit = "l10n_br_sped.efd_pis_cofins.6.d100"

    _odoo_model = "l10n_br_fiscal.document"

    @api.model
    def _odoo_domain(self, parent_record, declaration):
        documents = declaration._establishment_documents(
            parent_record, DOC_MODELS_D100
        ).filtered(lambda doc: doc.fiscal_operation_type == FISCAL_IN)
        return [("id", "in", documents.ids)]

    @api.model
    def _map_from_odoo(self, record, parent_record, declaration, index=0):
        return {
            "IND_OPER": "0",
            "IND_EMIT": "0" if record.issuer == DOCUMENT_ISSUER_COMPANY else "1",
            "COD_PART": str(record.partner_id.id),
            "COD_MOD": _cod_mod(record.document_type_id.code),
            "COD_SIT": COD_SIT_BY_STATE_EDOC.get(record.state_edoc, "00"),
            "SER": record.document_serie or "",
            "NUM_DOC": _digits(record.document_number),
            "CHV_CTE": record.document_key or "",
            "DT_DOC": _local_date(declaration, record.document_date),
            "DT_A_P": _local_date(
                declaration, record.date_in_out or record.document_date
            ),
            "TP_CTE": _spec(record, "cte40_tpCTe", ""),
            "VL_DOC": _document_total(record),
            "VL_DESC": record.amount_discount_value,
            "IND_FRT": "0",
            "VL_SERV": _document_total(record),
            "VL_BC_ICMS": record.amount_icms_base,
            "VL_ICMS": record.amount_icms_value,
        }


