class _ConsolidationMixin(models.AbstractModel):
    """M200 (PIS/PASEP) e M600 (COFINS), que têm os mesmos campos.

    O total vem do detalhe (M210/M610), que vem dos itens escriturados; a
    apuração do l10n_br_tax_assessment entra com o que só ela sabe: os ajustes
    manuais (M220/M620, onde a NT 12/2026 manda lançar a redução de
    benefícios da LC 224/2025) e as deduções. A diferença entre o débito
    apurado na contabilidade e o débito dos documentos é registrada no chatter
    da declaração (`_check_assessment_matches`).
    """

    _name = "l10n_br_sped.efd_pis_cofins.consolidation.mixin"
    _description = "Consolidação da contribuição do período (M200/M600)"

    _tax = "pis"

    @api.model
    def _pull_records_from_odoo(
        self, kind, level, parent_register=None, parent_record=None, log_msg=None
    ):
        declaration = self._context["declaration"]
        details = _contribution_details(self.env, declaration, self._tax)
        adjustments = _assessment_adjustments(self.env, declaration, self._tax)
        without_contribution = _revenue_without_contribution(
            self.env, declaration, self._tax
        )
        if not details and not adjustments and not without_contribution:
            self._log_chatter_sped_item(log_msg, level)
            return
        consolidation = self._build(declaration, details, adjustments)
        self._log_chatter_sped_item(log_msg, level, consolidation)

    def _build(self, declaration, details, adjustments):
        tax = self._tax
        up = tax.upper()
        detail_model = self.env[
            f"l10n_br_sped.efd_pis_cofins.m{'2' if tax == 'pis' else '6'}10"
        ]
        adjustment_model = self.env[
            f"l10n_br_sped.efd_pis_cofins.m{'2' if tax == 'pis' else '6'}20"
        ]
        receipt_model = self.env[
            f"l10n_br_sped.efd_pis_cofins.m{'2' if tax == 'pis' else '6'}05"
        ]
        parent_field = f"reg_M{'2' if tax == 'pis' else '6'}10_ids_RegistroM{'2' if tax == 'pis' else '6'}00_id"

        # NT 12/2026: o ajuste vincula-se ao M210/M610 da contribuição à
        # alíquota básica (01 no não cumulativo, 51 no cumulativo); se ele não
        # existir, cria-se um.
        for regime, adjs in adjustments.items():
            if not adjs:
                continue
            cod_cont = "01" if regime == "non_cumulative" else "51"
            if not any(d["COD_CONT"] == cod_cont for d in details):
                basic = (
                    NON_CUMULATIVE_BASIC_RATES
                    if regime == "non_cumulative"
                    else CUMULATIVE_BASIC_RATES
                )[tax]
                details.append(
                    {
                        "COD_CONT": cod_cont,
                        "ALIQ": basic,
                        "VL_REC_BRT": 0.0,
                        "VL_BC_CONT": 0.0,
                        "VL_CONT_APUR": 0.0,
                        "cumulative": regime == "cumulative",
                    }
                )

        totals = {"non_cumulative": 0.0, "cumulative": 0.0}
        detail_vals = []
        for detail in details:
            regime = "cumulative" if detail["cumulative"] else "non_cumulative"
            cod_cont_basic = "51" if detail["cumulative"] else "01"
            adjs = (
                adjustments.get(regime, [])
                if detail["COD_CONT"] == cod_cont_basic
                else []
            )
            increase = round(sum(a["VL_AJ"] for a in adjs if a["IND_AJ"] == "1"), 2)
            decrease = round(sum(a["VL_AJ"] for a in adjs if a["IND_AJ"] == "0"), 2)
            period = round(detail["VL_CONT_APUR"] + increase - decrease, 2)
            totals[regime] += period
            detail_vals.append(
                (
                    {
                        "COD_CONT": detail["COD_CONT"],
                        "VL_REC_BRT": detail["VL_REC_BRT"],
                        "VL_BC_CONT": detail["VL_BC_CONT"],
                        "VL_AJUS_ACRES_BC": 0.0,
                        "VL_AJUS_REDUC_BC": 0.0,
                        "VL_BC_CONT_AJUS": detail["VL_BC_CONT"],
                        f"ALIQ_{up}": detail["ALIQ"],
                        "VL_CONT_APUR": detail["VL_CONT_APUR"],
                        "VL_AJUS_ACRES": increase,
                        "VL_AJUS_REDUC": decrease,
                        "VL_CONT_PER": period,
                    },
                    adjs,
                )
            )

        assessments = {
            regime: _find_assessment(self.env, declaration, tax, regime)
            for regime in ("non_cumulative", "cumulative")
        }
        nc = assessments["non_cumulative"]
        cum = assessments["cumulative"]
        nc_total = round(totals["non_cumulative"], 2)
        cum_total = round(totals["cumulative"], 2)
        # Sem M100/M500 (crédito) nem 1100/1500 (controle de saldo credor) no
        # arquivo, os campos 03 e 04 só podem ser zero: o PVA confere cada um
        # com a soma dos registros que o detalham.
        nc_due = nc_total
        nc_deduction = min(nc.deduction_total, nc_due) if nc else 0.0
        cum_deduction = min(cum.deduction_total, cum_total) if cum else 0.0
        vals = {
            "VL_TOT_CONT_NC_PER": nc_total,
            "VL_TOT_CRED_DESC": 0.0,
            "VL_TOT_CRED_DESC_ANT": 0.0,
            "VL_TOT_CONT_NC_DEV": nc_due,
            "VL_RET_NC": 0.0,
            "VL_OUT_DED_NC": nc_deduction,
            "VL_CONT_NC_REC": round(nc_due - nc_deduction, 2),
            "VL_TOT_CONT_CUM_PER": cum_total,
            "VL_RET_CUM": 0.0,
            "VL_OUT_DED_CUM": cum_deduction,
            "VL_CONT_CUM_REC": round(cum_total - cum_deduction, 2),
        }
        vals["VL_TOT_CONT_REC"] = round(
            vals["VL_CONT_NC_REC"] + vals["VL_CONT_CUM_REC"], 2
        )
        consolidation = self.create(vals)

        for detail, adjs in detail_vals:
            detail[parent_field] = consolidation.id
            register = detail_model.create(detail)
            adj_parent = f"reg_M{'2' if tax == 'pis' else '6'}20_ids_RegistroM{'2' if tax == 'pis' else '6'}10_id"
            for adj in adjs:
                adjustment_model.create(dict(adj, **{adj_parent: register.id}))

        receipt_parent = f"reg_M{'2' if tax == 'pis' else '6'}05_ids_RegistroM{'2' if tax == 'pis' else '6'}00_id"
        for regime, field in (
            ("non_cumulative", "VL_CONT_NC_REC"),
            ("cumulative", "VL_CONT_CUM_REC"),
        ):
            if vals[field] > 0:
                receipt_model.create(
                    {
                        receipt_parent: consolidation.id,
                        "NUM_CAMPO": NUM_CAMPO_BY_REGIME[regime],
                        "COD_REC": COD_REC[(tax, regime)],
                        "VL_DEBITO": vals[field],
                    }
                )

        declaration._check_assessment_matches(tax, assessments, vals)
        return consolidation


