class _RevenueWithoutContributionMixin(models.AbstractModel):
    """M400 (PIS/PASEP) e M800 (COFINS): receitas sem contribuição."""

    _name = "l10n_br_sped.efd_pis_cofins.revenue.without.contribution.mixin"
    _description = "Receitas sem contribuição (M400/M800)"

    _tax = "pis"

    @api.model
    def _pull_records_from_odoo(
        self, kind, level, parent_register=None, parent_record=None, log_msg=None
    ):
        declaration = self._context["declaration"]
        tax = self._tax
        digit = "4" if tax == "pis" else "8"
        detail_model = self.env[f"l10n_br_sped.efd_pis_cofins.m{digit}10"]
        parent_field = f"reg_M{digit}10_ids_RegistroM{digit}00_id"
        created = self.browse()
        groups = _revenue_without_contribution(self.env, declaration, tax)
        for cst, group in groups.items():
            # COD_CTA é obrigatório no M400/M800 de quem apura no não
            # cumulativo; com mais de uma conta, vai a de maior receita, e o
            # M410/M810 traz cada conta com o seu valor.
            by_account = {}
            for (_nat_rec, cod_cta), value in group["NAT_REC"].items():
                by_account[cod_cta] = by_account.get(cod_cta, 0.0) + value
            main_account = max(by_account, key=by_account.get) if by_account else ""
            register = self.create(
                {
                    f"CST_{tax.upper()}": cst,
                    "VL_TOT_REC": round(group["VL_TOT_REC"], 2),
                    "COD_CTA": main_account,
                }
            )
            created |= register
            # Guia 1.35, Registro M410: um por natureza da receita (tabelas
            # 4.3.10 a 4.3.16), que vem do NCM do produto.
            for (nat_rec, cod_cta), value in group["NAT_REC"].items():
                detail_model.create(
                    {
                        parent_field: register.id,
                        "NAT_REC": nat_rec,
                        "VL_REC": round(value, 2),
                        "COD_CTA": cod_cta,
                    }
                )
        self._log_chatter_sped_item(log_msg, level, created)


